339: function spawnWorld() {
340:   game.mobs.length = 0;
341:   game.flowers.length = 0;
342:   game.puddles.length = 0;
343:   game.particles.length = 0;
344:   game.texts.length = 0;
345:   game.motes.length = 0;
346: 
347:   for (let zi = 0; zi < ZONES.length; zi++) {
348:     const zone = ZONES[zi];
349:     makePuddles(zi);
350:     for (const [type, count] of Object.entries(zone.spawns)) {
351:       for (let i = 0; i < count; i++) {
352:         const pt = randomZonePoint(zone, true);
353:         if (type === 'nectar') game.flowers.push(makeFlower(pt.x, pt.y, zi));
354:         else game.mobs.push(makeMob(type, pt.x, pt.y, zi));
355:       }
356:     }
357:   }
358:   game.boss = makeBoss();
359:   game.mobs.push(game.boss);
360:   seedMotes();
361: }
