363: function seedMotes() {
364:   const zi = game.zoneIndex;
365:   const kinds = ['garden', 'meadow', 'edge', 'deep'];
366:   const kind = kinds[zi];
367:   game.motes.length = 0;
368:   for (let i = 0; i < 70; i++) {
369:     game.motes.push({
370:       x: Math.random() * WORLD_W,
371:       y: Math.random() * WORLD_H,
372:       phase: Math.random() * TAU,
373:       speed: between(Math.random, 0.2, 1),
374:       size: between(Math.random, 0.7, 2.1),
375:       kind: kind === 'edge' || kind === 'deep'
376:         ? (Math.random() > 0.45 ? 'firefly' : 'spore')
377:         : (Math.random() > 0.6 ? 'fluff' : 'pollen'),
378:       depth: between(Math.random, 0.4, 1.2),
379:     });
380:   }
381: }
