383: function initWorld(save) {
384:   game.state = 'loading';
385:   game.player = createPlayerData(save ? save.stage : 0);
386:   game.stage = game.player.stage;
387:   game.biomass = save ? save.biomass : 0;
388:   game.eaten = save ? save.eaten : 0;
389:   game.playTime = save ? save.time : 0;
390:   game.bossDead = save ? !!save.bossDead : false;
391:   game.bossEngaged = false;
392:   game.time = 0;
393:   game.shake = 0; game.hurtFlash = 0; game.slowmo = 0; game.winTimer = 0;
394:   game.drinking = false; game.blocked = false; game.toughCd = 0; game.flowerCd = 0;
395:   game.saveAt = 0; game.toastTimer = 0; game.introTimer = 0; game.bossIntro = false;
396:   setStage(game.stage, true);
397: 
398:   const p = game.player;
399:   if (save) {
400:     p.x = clamp(save.x || 500, 60, WORLD_W - 60);
401:     p.y = clamp(save.y || pathY(p.x), 60, WORLD_H - 60);
402:     p.hp = clamp(save.hp || p.maxHp, 1, p.maxHp);
403:     p.hunger = clamp(save.hunger ?? 70, 0, 100);
404:     p.thirst = clamp(save.thirst ?? 62, 0, 100);
405:   } else {
406:     p.x = 500;
407:     p.y = pathY(500);
408:   }
409:   // never restore beyond an unopened gate
410:   for (const b of BARRIERS) {
411:     if (game.stage < b.require && p.x > b.x - 50) p.x = b.x - 50;
412:   }
413:   p.y = clamp(p.y, 70, WORLD_H - 70);
414:   game.zoneIndex = zoneIndexAt(p.x);
415:   spawnWorld();
416:   if (game.bossDead && game.boss) {
417:     game.boss.alive = false;
418:     game.boss.respawn = 0;
419:     game.boss.sleeping = true;
420:   }
421:   game.cam.x = p.x;
422:   game.cam.y = p.y;
423:   game.cam.zoom = 1.02 - game.stage * 0.025;
424:   clampCamera(true);
425:   game.state = 'playing';
426:   game.hintCd = 0;
427: }
