460: // ————————————————————————————————————————————————
461: // update — playing
462: // ————————————————————————————————————————————————
463: 
464: function updatePlaying(dt) {
465:   const slow = game.slowmo > 0 ? 0.38 : 1;
466:   const sdt = dt * slow;
467:   game.time += sdt;
468:   game.playTime += dt;
469:   game.slowmo = Math.max(0, game.slowmo - dt);
470: 
471:   updatePlayer(sdt);
472:   updateFlowers(sdt);
473:   for (const c of game.mobs) updateMob(c, sdt);
474:   resolveHazards(sdt);
475:   updateCombat(sdt);
476:   updateParticles(sdt);
477:   updateTexts(sdt);
478:   updateMotes(sdt);
479:   updateCamera(dt);
480:   updateTimers(dt);
481:   sound.update(dt, ZONES[game.zoneIndex].id, game.state === 'playing');
482: 
483:   if (game.state !== 'playing') return;
484:   if (game.winTimer > 0) {
485:     game.winTimer -= dt;
486:     if (game.winTimer <= 0) showWin();
487:   }
488: }
489: 
490: function updatePlayer(dt) {
491:   const p = game.player;
492:   const st = STAGES[game.stage];
493:   p.attackCd -= dt;
494:   p.hurtT = Math.max(0, p.hurtT - dt);
495:   p.dashT = Math.max(0, p.dashT - dt);
496:   p.dashCd = Math.max(0, p.dashCd - dt);
497:   p.biteT = Math.max(0, p.biteT - dt);
498:   game.toughCd = Math.max(0, game.toughCd - dt);
499:   game.flowerCd = Math.max(0, game.flowerCd - dt);
500: 
501:   const inp = inputVector();
502:   if (dashQueued) {
503:     dashQueued = false;
504:     if (st.dash && p.dashCd <= 0) {
505:       // dash toward the stick/key direction, or straight ahead when standing still
506:       let dx = inp.x, dy = inp.y;
507:       if (inp.mag <= 0.12) {
508:         dx = Math.cos(p.angle);
509:         dy = Math.sin(p.angle);
510:       }
511:       const l = Math.hypot(dx, dy) || 1;
512:       p.dashVX = (dx / l) * st.speed * 2.8;
513:       p.dashVY = (dy / l) * st.speed * 2.8;
514:       p.dashT = 0.17;
515:       p.dashCd = 0.55;
516:       p.angle = Math.atan2(dy, dx);
517:       sound.dash();
518:       for (let i = 0; i < 7; i++) {
519:         burst(p.x - dx * 10, p.y - dy * 10, '#c9c6a4', 1, {
520:           speed: 40, life: 0.5, size: 2.4, type: 'dust',
521:         });
522:       }
523:       game.shake = Math.max(game.shake, 1.5);
524:     }
525:   }
526: 
527:   let speed = st.speed;
528:   const pathDist = Math.abs(p.y - pathY(p.x));
529:   if (game.zoneIndex >= 2 && pathDist > 300) speed *= 0.84;
530:   if (game.drinking) speed *= 0.94;
531: 
532:   if (p.dashT > 0) {
533:     p.vx = p.dashVX;
534:     p.vy = p.dashVY;
535:   } else {
536:     const targetVX = inp.x * speed * inp.mag;
537:     const targetVY = inp.y * speed * inp.mag;
538:     const k = 1 - Math.exp(-dt * (inp.mag > 0 ? 10 : 7));
539:     p.vx = lerp(p.vx, targetVX, k);
540:     p.vy = lerp(p.vy, targetVY, k);
541:   }
542: 
543:   p.x += p.vx * dt;
544:   p.y += p.vy * dt;
545:   p.x = clamp(p.x, 26, WORLD_W - 26);
546:   p.y = clamp(p.y, 52, WORLD_H - 52);
547: 
548:   // zone gates
549:   game.blocked = false;
550:   for (const b of BARRIERS) {
551:     if (game.stage < b.require) {
552:       if (p.x > b.x - 30) {
553:         p.x = b.x - 30;
554:         p.vx = Math.min(0, p.vx);
555:       }
556:       // latch the hint while the player is pressed against the thicket
557:       if (p.x >= b.x - 36) game.blocked = true;
558:     }
559:   }
560: 
561:   const sp = Math.hypot(p.vx, p.vy);
562:   if (sp > 20) {
563:     p.angle = lerpAngle(p.angle, Math.atan2(p.vy, p.vx), 1 - Math.exp(-dt * 12));
564:     p.walk += dt * (5 + sp * 0.07);
565:   } else {
566:     p.walk += dt * 1.1;
567:   }
568: 
569:   // water
570:   game.drinking = false;
571:   for (const pd of game.puddles) {
572:     pd.drinking = false;
573:     const ex = (p.x - pd.x) / pd.rx;
574:     const ey = (p.y - pd.y) / pd.ry;
575:     if (ex * ex + ey * ey < 1 && p.thirst < 99.99) {
576:       pd.drinking = true;
577:       game.drinking = true;
578:       p.thirst = Math.min(100, p.thirst + 52 * dt);
579:       game.splashCd -= dt;
580:       if (game.splashCd <= 0) {
581:         game.splashCd = 0.34;
582:         burst(p.x, p.y + 2, '#cfe3d8', 3, { speed: 22, life: 0.6, size: 1.8, type: 'drop', gravity: 20 });
583:         if (Math.random() > 0.5) sound.drink();
584:       }
585:     }
586:   }
587: 
588:   // tiny bites of nectar
589:   for (const f of game.flowers) {
590:     if (f.nectar <= 0) continue;
591:     if (dist2(p.x, p.y, f.x, f.y) < (p.r + f.r + 7) ** 2 && game.flowerCd <= 0) {
592:       f.nectar = 0;
593:       f.respawn = between(Math.random, FLOWER_RESPAWN[0], FLOWER_RESPAWN[1]);
594:       p.hunger = Math.min(100, p.hunger + 4);
595:       p.thirst = Math.min(100, p.thirst + 6);
596:       game.biomass += 1;
597:       game.flowerCd = 0.3;
598:       addText(f.x, f.y - 12, '+nectar', '#6d6a3f', 12);
599:       burst(f.x, f.y, f.heart, 8, { speed: 55, life: 0.8, size: 2.2, type: 'dot', gravity: 10 });
600:     }
601:   }
602: 
603:   // vitals
604:   p.hunger = clamp(p.hunger - st.hungerDrain * dt, 0, 100);
605:   p.thirst = clamp(p.thirst - st.thirstDrain * dt, 0, 100);
606:   if (p.hunger <= 0) p.hp -= 1.5 * dt;
607:   if (p.thirst <= 0) p.hp -= 2.2 * dt;
608:   if (p.hunger > 35 && p.thirst > 35) p.hp = Math.min(p.maxHp, p.hp + 1.0 * dt);
609:   p.hp = Math.min(p.hp, p.maxHp);
610:   if (p.hp <= 0 && game.state === 'playing') die();
611: 
612:   // zone change
613:   const zi = zoneIndexAt(p.x);
614:   if (zi !== game.zoneIndex) {
615:     game.zoneIndex = zi;
616:     seedMotes();
617:     enterZone(ZONES[zi]);
618:     sound.setZone(ZONES[zi].id);
619:     if (zi === 3 && game.stage >= 4 && !game.bossDead && !game.bossIntro) {
620:       game.bossIntro = true;
621:       flash('Something enormous is breathing in the roots.', 4200);
622:     }
623:   }
624: }
625: 
626: function updateFlowers(dt) {
627:   for (const f of game.flowers) {
628:     if (f.nectar <= 0) {
629:       f.respawn -= dt;
630:       if (f.respawn <= 0) {
631:         f.nectar = 1;
632:         burst(f.x, f.y, f.heart, 5, { speed: 22, life: 1.2, size: 1.4, type: 'dot' });
633:       }
634:     }
635:   }
636: }
637: 
638: function updateMob(c, dt) {
639:   if (!c.alive) {
640:     if (c.respawn > 0) {
641:       c.respawn -= dt;
642:       if (c.respawn <= 0) respawnMob(c);
643:     }
644:     return;
645:   }
646:   if (c.boss) { updateBoss(c, dt); return; }
647: 
648:   const p = game.player;
649:   const dx = p.x - c.x, dy = p.y - c.y;
650:   const d = Math.hypot(dx, dy) || 1;
651:   c.attackCd = Math.max(0, c.attackCd - dt);
652:   c.fleeT -= dt;
653:   c.restT -= dt;
654: 
655:   const canEat = game.stage >= c.def.tier;
656:   const dangerous = c.def.threat > 0 && game.stage <= c.def.tier;
657:   let ax = 0, ay = 0;
658:   let speed = c.def.speed;
659: 
660:   if (dangerous && d < c.def.aggro) {
661:     c.aggro = true;
662:     ax = dx / d;
663:     ay = dy / d;
664:     const weave = Math.sin(game.time * 2.6 + c.seed) * 0.32;
665:     ax += -dy / d * weave;
666:     ay += dx / d * weave;
667:     speed = c.def.speed * 1.1;
668:   } else if (canEat && d < 300) {
669:     c.aggro = false;
670:     if (c.fleeT <= 0 && c.restT <= 0) {
671:       c.fleeT = 0.62;
672:       c.restT = 1.0 + Math.random() * 0.7;
673:     }
674:     if (c.fleeT > 0) {
675:       ax = -dx / d;
676:       ay = -dy / d;
677:       speed = c.def.burst;
678:     }
679:   } else {
680:     c.aggro = false;
681:   }
682: 
683:   if (!ax && !ay) {
684:     const wa = c.seed * 1.7 + game.time * 0.55;
685:     ax = Math.cos(wa) * 0.4;
686:     ay = Math.sin(wa * 1.31) * 0.4;
687:     const hdx = c.homeX - c.x, hdy = c.homeY - c.y;
688:     const hd = Math.hypot(hdx, hdy) || 1;
689:     if (hd > 230) {
690:       ax += hdx / hd * 1.4;
691:       ay += hdy / hd * 1.4;
692:     }
693:   }
694: 
695:   const al = Math.hypot(ax, ay) || 1;
696:   const kv = 1 - Math.exp(-dt * (c.aggro ? 5 : 3.4));
697:   c.vx = lerp(c.vx, (ax / al) * speed, kv);
698:   c.vy = lerp(c.vy, (ay / al) * speed, kv);
699:   c.x += (c.vx + c.kvx) * dt;
700:   c.y += (c.vy + c.kvy) * dt;
701:   c.kvx *= Math.exp(-dt * 6);
702:   c.kvy *= Math.exp(-dt * 6);
703: 
704:   const zone = ZONES[c.zone];
705:   c.x = clamp(c.x, zone.x0 + 16, zone.x1 - 16);
706:   c.y = clamp(c.y, 48, WORLD_H - 48);
707: 
708:   const v = Math.hypot(c.vx, c.vy);
709:   if (v > 8) c.angle = lerpAngle(c.angle, Math.atan2(c.vy, c.vx), 1 - Math.exp(-dt * 8));
710:   c.walk += dt * (2 + v * 0.06);
711: }
712: 
713: function updateBoss(c, dt) {
714:   if (!c.alive) return;
715:   const p = game.player;
716:   const dx = p.x - c.x, dy = p.y - c.y;
717:   const d = Math.hypot(dx, dy) || 1;
718:   c.attackCd = Math.max(0, c.attackCd - dt);
719: 
720:   if (c.sleeping) {
721:     if (game.stage >= 4 && d < 620) {
722:       c.sleeping = false;
723:       c.waking = 1.3;
724:       c.aggro = true;
725:       c.state = 'idle';
726:       game.bossEngaged = true;
727:       game.shake = 9;
728:       sound.boss();
729:       flash('The Mantis Queen unfolds from the roots.', 4400);
730:       burst(c.x, c.y, '#d9c98d', 18, { speed: 120, life: 1.4, size: 2.5, type: 'dot' });
731:     } else {
732:       c.walk += dt * 0.4;
733:       return;
734:     }
735:   }
736: 
737:   if (c.waking > 0) {
738:     c.waking -= dt;
739:     c.vx *= Math.exp(-dt * 6);
740:     c.vy *= Math.exp(-dt * 6);
741:     c.x += c.vx * dt;
742:     c.y += c.vy * dt;
743:     return;
744:   }
745: 
746:   if (d > 1080) {
747:     c.aggro = false;
748:     game.bossEngaged = false;
749:     const hdx = c.homeX - c.x, hdy = c.homeY - c.y;
750:     const hd = Math.hypot(hdx, hdy) || 1;
751:     c.vx = lerp(c.vx, hdx / hd * 95, 1 - Math.exp(-dt * 3));
752:     c.vy = lerp(c.vy, hdy / hd * 95, 1 - Math.exp(-dt * 3));
753:     c.x += c.vx * dt;
754:     c.y += c.vy * dt;
755:     c.angle = lerpAngle(c.angle, Math.atan2(hdy, hdx), 1 - Math.exp(-dt * 6));
756:     c.walk += dt * 2;
757:     return;
758:   }
759: 
760:   c.aggro = true;
761:   game.bossEngaged = true;
762:   c.lungeCd -= dt;
763: 
764:   if (c.state === 'idle') {
765:     const weave = Math.sin(game.time * 1.7 + c.seed) * 0.6;
766:     let ax = dx / d - (dy / d) * weave;
767:     let ay = dy / d + (dx / d) * weave;
768:     const al = Math.hypot(ax, ay) || 1;
769:     c.vx = lerp(c.vx, (ax / al) * 152, 1 - Math.exp(-dt * 3.2));
770:     c.vy = lerp(c.vy, (ay / al) * 152, 1 - Math.exp(-dt * 3.2));
771:     if (d < 370 && c.lungeCd <= 0) {
772:       c.state = 'telegraph';
773:       c.tele = 0.62;
774:       c.vx *= 0.15;
775:       c.vy *= 0.15;
776:     }
777:   } else if (c.state === 'telegraph') {
778:     c.tele -= dt;
779:     c.vx *= Math.exp(-dt * 8);
780:     c.vy *= Math.exp(-dt * 8);
781:     if (c.tele <= 0) {
782:       c.state = 'lunge';
783:       c.lungeT = 0.37;
784:       c.lungeVX = (dx / d) * 660;
785:       c.lungeVY = (dy / d) * 660;
786:       game.shake = 7;
787:       sound.boss();
788:     }
789:   } else if (c.state === 'lunge') {
790:     c.lungeT -= dt;
791:     c.vx = c.lungeVX;
792:     c.vy = c.lungeVY;
793:     if (Math.random() > 0.7) {
794:       burst(c.x - c.vx * 0.02, c.y - c.vy * 0.02, '#c8bd92', 1, { speed: 20, life: 0.5, size: 2.4, type: 'dust' });
795:     }
796:     if (c.lungeT <= 0) {
797:       c.state = 'recover';
798:       c.recoverT = 0.85;
799:       c.lungeCd = 2.5 + Math.random() * 0.9;
800:     }
801:   } else {
802:     c.recoverT -= dt;
803:     c.vx *= Math.exp(-dt * 5);
804:     c.vy *= Math.exp(-dt * 5);
805:     if (c.recoverT <= 0) c.state = 'idle';
806:   }
807: 
808:   c.x += c.vx * dt;
809:   c.y += c.vy * dt;
810:   c.x = clamp(c.x, 5480, WORLD_W - 40);
811:   c.y = clamp(c.y, 80, WORLD_H - 80);
812: 
813:   const face = c.state === 'lunge' ? Math.atan2(c.vy, c.vx) : Math.atan2(dy, dx);
814:   c.angle = lerpAngle(c.angle, face, 1 - Math.exp(-dt * 7));
815:   c.walk += dt * (1.2 + Math.hypot(c.vx, c.vy) * 0.012);
816: }
817: 
818: function respawnMob(c) {
819:   const zone = ZONES[c.zone];
820:   let pt = randomZonePoint(zone, true);
821:   for (let i = 0; i < 8 && dist(pt.x, pt.y, game.player.x, game.player.y) < 460; i++) {
822:     pt = randomZonePoint(zone, true);
823:   }
824:   c.x = pt.x; c.y = pt.y;
825:   c.homeX = pt.x; c.homeY = pt.y;
826:   c.vx = 0; c.vy = 0; c.kvx = 0; c.kvy = 0;
827:   c.hp = c.def.hp;
828:   c.alive = true;
829:   c.aggro = false;
830:   c.fleeT = 0; c.restT = 0;
831:   c.state = 'idle';
832: }
833: 
834: // ————————————————————————————————————————————————
835: // combat
836: // ————————————————————————————————————————————————
837: 
838: function updateCombat(dt) {
839:   const p = game.player;
840:   if (p.attackCd > 0) return;
841:   let target = null;
842:   let best = Infinity;
843:   for (const c of game.mobs) {
844:     if (!c.alive || c.sleeping) continue;
845:     const reach = p.r + c.r + (c.boss ? 16 : 7);
