1295: function drawAtmosphere(c) {
1296:   const zone = ZONES[game.zoneIndex];
1297:   const w = view.w, h = view.h;
1298:   if (zone.palette === 'garden') {
1299:     const g = c.createRadialGradient(w * 0.72, h * 0.12, 0, w * 0.72, h * 0.12, Math.max(w, h) * 0.75);
1300:     g.addColorStop(0, 'rgba(255,238,178,0.16)');
1301:     g.addColorStop(0.5, 'rgba(255,238,178,0.05)');
1302:     g.addColorStop(1, 'rgba(255,238,178,0)');
1303:     c.fillStyle = g;
1304:     c.fillRect(0, 0, w, h);
1305:   } else if (zone.palette === 'meadow') {
1306:     const g = c.createLinearGradient(0, 0, 0, h);
1307:     g.addColorStop(0, 'rgba(255,228,150,0.09)');
1308:     g.addColorStop(0.6, 'rgba(255,228,150,0.02)');
1309:     g.addColorStop(1, 'rgba(210,180,110,0.05)');
1310:     c.fillStyle = g;
1311:     c.fillRect(0, 0, w, h);
1312:   } else if (zone.palette === 'edge') {
1313:     const g = c.createLinearGradient(0, 0, 0, h);
1314:     g.addColorStop(0, 'rgba(225,225,205,0.18)');
1315:     g.addColorStop(0.45, 'rgba(225,225,205,0.03)');
1316:     g.addColorStop(1, 'rgba(40,60,48,0.08)');
1317:     c.fillStyle = g;
1318:     c.fillRect(0, 0, w, h);
1319:   } else {
1320:     c.fillStyle = 'rgba(27,48,43,0.16)';
1321:     c.fillRect(0, 0, w, h);
1322:     // god rays through the canopy
1323:     c.save();
1324:     c.translate(w * 0.62, -h * 0.2);
1325:     c.rotate(0.34);
1326:     for (let i = 0; i < 4; i++) {
1327:       const x = i * Math.max(90, w * 0.09);
1328:       const bw = Math.max(26, w * 0.035);
1329:       const g = c.createLinearGradient(x, 0, x, h * 1.6);
1330:       g.addColorStop(0, 'rgba(245,238,190,0.12)');
1331:       g.addColorStop(0.45, 'rgba(245,238,190,0.05)');
1332:       g.addColorStop(1, 'rgba(245,238,190,0)');
1333:       c.fillStyle = g;
1334:       c.fillRect(x, 0, bw, h * 1.6);
1335:     }
1336:     c.restore();
1337:     const warm = c.createRadialGradient(w * 0.8, h * 0.45, 0, w * 0.8, h * 0.45, Math.min(w, h) * 0.6);
1338:     warm.addColorStop(0, 'rgba(240,224,160,0.1)');
1339:     warm.addColorStop(1, 'rgba(240,224,160,0)');
1340:     c.fillStyle = warm;
1341:     c.fillRect(0, 0, w, h);
1342:   }
1343: }
