1345: function drawVignette(c) {
1346:   const w = view.w, h = view.h;
1347:   const g = c.createRadialGradient(w / 2, h * 0.48, Math.min(w, h) * 0.28, w / 2, h * 0.5, Math.max(w, h) * 0.72);
1348:   g.addColorStop(0, 'rgba(54,56,38,0)');
