1353: 
1354:   if (game.hurtFlash > 0) {
1355:     const r = c.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.2, w / 2, h / 2, Math.max(w, h) * 0.7);
1356:     r.addColorStop(0, 'rgba(150,50,40,0)');
1357:     r.addColorStop(1, `rgba(150,50,40,${game.hurtFlash * 0.22})`);
