1361:   const p = game.player;
1362:   if (p && p.hp / p.maxHp < 0.28 && game.state === 'playing') {
1363:     const pulse = 0.5 + 0.5 * Math.sin(game.time * 5);
1364:     const r = c.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.7);
1365:     r.addColorStop(0, 'rgba(120,40,36,0)');
1366:     r.addColorStop(1, `rgba(120,40,36,${0.08 + pulse * 0.1})`);
