7: function shadow(ctx, x, y, rx, ry, alpha = 0.2) {
8:   const g = ctx.createRadialGradient(x, y, 0, x, y, Math.max(rx, ry));
9:   g.addColorStop(0, `rgba(52,58,38,${alpha})`);
10:   g.addColorStop(0.6, `rgba(52,58,38,${alpha * 0.55})`);
11:   g.addColorStop(1, 'rgba(52,58,38,0)');
12:   ctx.save();
13:   ctx.translate(x, y);
14:   ctx.scale(1, ry / rx);
15:   ctx.fillStyle = g;
16:   ctx.beginPath();
17:   ctx.arc(0, 0, rx, 0, TAU);
18:   ctx.fill();
19:   ctx.restore();
20: }
