22: function leg(ctx, hx, hy, side, phase, scale, color, ink, width = 1) {
23:   const swing = Math.sin(phase) * 2.2 * scale;
24:   const hipY = hy + side * 3.0 * scale;
25:   const kx = hx - 1.4 * scale + swing * 0.3;
26:   const ky = hy + side * 6.4 * scale;
27:   const fx = hx - 6.0 * scale + swing;
28:   const fy = hy + side * 10.0 * scale;
29:   ctx.beginPath();
30:   ctx.moveTo(hx, hipY);
31:   ctx.quadraticCurveTo(kx, ky, fx, fy);
32:   ctx.strokeStyle = hexA(ink, 0.55);
33:   ctx.lineWidth = 1.8 * scale * width;
34:   ctx.lineCap = 'round';
35:   ctx.stroke();
36:   ctx.strokeStyle = hexA(color, 0.65);
37:   ctx.lineWidth = 0.8 * scale * width;
38:   ctx.stroke();
39:   ctx.fillStyle = hexA(ink, 0.45);
40:   ctx.beginPath();
41:   ctx.arc(fx, fy, 0.8 * scale, 0, TAU);
42:   ctx.fill();
43: }
