45: function legs(ctx, hips, phase, scale, color, ink, width = 1) {
46:   for (const side of [-1, 1]) {
47:     hips.forEach((hx, i) => {
48:       leg(ctx, hx, 0, side, phase + i * 1.9 + (side > 0 ? Math.PI : 0), scale, color, ink, width);
49:     });
50:   }
