89:   ctx.save();
90:   ctx.translate(p.x, p.y);
91: 
92:   // a pale watercolor halo keeps the player legible against the painted ground
93:   softBlob(ctx, 0, 0, r * 2.9, r * 2.4, '#fff7d6', stage === 4 ? 0.34 : 0.26);
94:   softBlob(ctx, 0, 0, r * 1.5, r * 1.3, '#fffbe8', 0.18);
95:   shadow(ctx, 2.5, r * 0.62, r * 1.25, r * 0.55, 0.24);
96: 
97:   if (stage === 4) {
98:     // radiant aura
99:     softBlob(ctx, 0, 0, r * 3.1, r * 2.8, '#d9d38a', 0.16);
100:     for (let i = 0; i < 3; i++) {
101:       const a = t * 0.7 + i * 2.1;
102:       ctx.fillStyle = 'rgba(240,236,182,0.45)';
103:       ctx.beginPath();
104:       ctx.arc(Math.cos(a) * r * 1.7, Math.sin(a) * r * 1.5, 1.4, 0, TAU);
105:       ctx.fill();
106:     }
107:   }
108: 
109:   ctx.rotate(p.angle || 0);
110:   const bite = p.biteT > 0;
